mapper.update:
UPDATE SMT_AUTH_RESOURCE_COORD R
		SET R.BLOCKING_TARGET_ID=NULL,R.BLOCKING_ATTEMPT_ID=NULL,R.BLOCK_REASON=NULL,R.UPDATE_TIME=#{now}
		WHERE R.ID=#{resourceId} AND R.GENERATION=#{operationVersion}
		AND R.BLOCKING_TARGET_ID=#{targetId} AND R.BLOCKING_ATTEMPT_ID=#{attemptId}
		AND R.APPLIED_GENERATION<R.GENERATION
